export interface WorkflowNodeAnalysis {
  state: 'ready' | 'missing_inputs' | 'invalid_params' | 'schema_mismatch';
  tone: 'green' | 'gold' | 'red';
  summary: string;
  issues: WorkflowValidationIssue[];
}

function hasRequiredValue(
  value: unknown,
  fieldType: WorkflowNodeCatalogItem['params'][number]['fieldType'],
): boolean {
  if (fieldType === 'boolean') {
    return typeof value === 'boolean';
  }
  if (fieldType === 'number') {
    return typeof value === 'number' && Number.isFinite(value);
  }
  if (fieldType === 'multiselect') {
    return Array.isArray(value) && value.length > 0;
  }
  return typeof value === 'string' ? value.trim().length > 0 : value !== undefined && value !== null;
}

def validate_workflow_graph(
    graph: WorkflowGraph,
    *,
    dataset_semantics_resolver: DatasetSemanticsResolver | None = None,
    _inside_subgraph: bool = False,
) -> WorkflowValidationResult:
    issues: list[WorkflowValidationIssue] = []

    node_ids = [node.id for node in graph.nodes]
    duplicates = [node_id for node_id, count in Counter(node_ids).items() if count > 1]
    for node_id in duplicates:
        issues.append(
            _issue(
                "duplicate_node_id",
                f"Duplicate node id: {node_id}",
                node_id=node_id,
                suggestion="Rename one of the duplicated nodes before saving the workflow.",
            )
        )

    definitions = _definition_map()
    supported_types = supported_node_types()
    nodes_by_id = {node.id: node for node in graph.nodes}

    for node in graph.nodes:
        if node.type not in supported_types:
            issues.append(
                _issue(
                    "unsupported_node_type",
                    f"Unsupported node type: {node.type}",
                    node_id=node.id,
                    actual=node.type,
                )
            )
            continue

