    }
    // 后续逻辑持续读取、匹配、记录审计事件，直到命中、超时或取消。
}

func (c *Client) RestoreBagPetStatusContext(ctx context.Context, timeout time.Duration) (packets.PetStatusRestore2306Result, error) {
    if ctx == nil {
        ctx = context.Background()
    }
    if _, err := c.RequestRestoreBagPetStatus(); err != nil {
        return packets.PetStatusRestore2306Result{}, err
    }

    packet, err := c.gateway.WaitCommandWithTimeoutContext(ctx, protocol.CmdRestoreBagPetStatus, timeout)
