func NewServer(opts Options) *Server {
    paths := opts.RuntimePaths
    if strings.TrimSpace(paths.DataDir) == "" && strings.TrimSpace(paths.CacheDir) == "" {
        paths = runtimepaths.FromEnv()
    } else {
        paths = paths.WithDefaults()
    }

    s := &Server{
        mux:           http.NewServeMux(),
        runtimePaths:  paths,
        accountStores: newAccountScopedStoreRegistry(paths),
        accountPrefs:  accountprefs.NewStore(paths),
        loginVault:    loginvault.NewStore(paths, now),
        pvpStrategyStores: newPVPStrategyStoreRegistry(paths),
    }

    instance := s.newConnectionInstance(localToolUserID, defaultConnectionInstanceID, "默认连接", opts.SessionManager)
    s.instances = NewConnectionInstanceManager(instance)
    s.sessions = instance.sessions
    s.battle = instance.battle
    s.battleActions = instance.battleAction
    s.packetAudit = instance.packetAudit
    s.dailyRuns = instance.dailyRuns
    s.routes()
    return s
}

type Service struct {
    Session *Session
}

func NewService() *Service {
    return &Service{Session: NewSession()}
}

func (s *Service) ApplyReadyPacket(packet packets.FightNoteReady2503, selfUserID uint32) ReadyState {
    ready := ReadyStateFrom2503(packet, selfUserID)
    s.Session.ApplyReady(ready)
    return ready
}

func (s *Service) ApplySkillPacket(packet packets.FightNoteUseSkill2505) SkillTurn {
    turn := SkillTurnFrom2505(packet)
    s.Session.ApplySkillTurn(turn)
    return turn
}

func (s *Service) ApplyFightOverPacket(packet packets.FightOver2506) FightOver {
    over := FightOverFrom2506(packet)
    s.Session.ApplyFightOver(over)
    return over
}

func ReadyStateFrom2503(packet packets.FightNoteReady2503, selfUserID uint32) ReadyState {
    ready := ReadyState{
        Mode:        packet.Mode,
        EFFightType: packet.EFFightType,
        SelfUserID:  selfUserID,
        MyIndex:     -1,
        RivalIndex:  -1,
        Fighters:    make([]ReadyFighter, 0, len(packet.Fighters)),
    }

    for i, fighter := range packet.Fighters {
        isRival := fighter.UserID != selfUserID
        modelFighter := readyFighterFrom2503(fighter, isRival)
        if fighter.UserID == selfUserID {
            ready.MyIndex = i
        } else {
            ready.RivalIndex = i
        }
        ready.Fighters = append(ready.Fighters, modelFighter)
    }
    return ready
}

func (s *Server) previewBattleStrategyDecisionForRuntime(
    ctx context.Context,
    runtime *BattleRuntime,
    instance *ConnectionInstance,
) (battleStrategyDecision, error) {
    if runtime == nil {
        return battleStrategyDecision{}, fmt.Errorf("battle runtime is not initialized")
    }
    decision, err := runtime.DecisionContext()
    if err != nil {
        return battleStrategyDecision{}, err
    }
    decision = s.enrichDecisionContext(ctx, decision)
    executionState := runtime.StrategyExecutionState()
    result := battleStrategyDecision{
        Context: decision,
        Preview: pvpstrategy.PreviewWithExecutionState(
            decision,
            s.runtimePolicyForDecisionForInstance(instance, decision),
            executionState,
        ),
        Settings: runtime.Settings(),
    }
    return withAutoBattleControlItemFallback(result), nil
}

func evaluateSkillAction(ctx battle.DecisionContext, plan ActionPlan, action ActionToken, skillID uint32) (*ActionDecision, string) {
    if skillID == 0 {
        return nil, "技能 ID 为空"
    }
    if !ctx.CanAct {
        return nil, "当前还不能行动"
    }
    if ctx.NeedsForcedSwitch {
        return nil, "当前必须先换宠，不能出招"
    }
    if !ctx.Self.Active.Alive {
        return nil, "我方当前精灵已死亡"
    }
    skill, ok := findSkill(ctx.Self.Active.Skills, skillID)
    if !ok {
        return nil, fmt.Sprintf("当前技能栏没有技能 %d", skillID)
    }
    if !skill.Usable {
        return nil, skill.UnavailableReason
    }
    return &ActionDecision{
        Action:     action,
        PlanID:     plan.ID,
        Reason:     fmt.Sprintf("技能 %d 当前可用", skillID),
        SkillID:    skillID,
        Executable: true,
    }, ""
}

