const (
    HeaderSize    = 17
    MaxPacketSize = 8 << 20
)

type Packet struct {
    Length  uint32
    Version byte
    CmdID   uint32
    UserID  uint32
    SN      uint32
    Body    []byte
}

func ParsePacket(data []byte) (Packet, error) {
    if len(data) < HeaderSize {
        return Packet{}, fmt.Errorf("packet too short: got %d bytes", len(data))
    }
    length := binary.BigEndian.Uint32(data[:4])
    if length < HeaderSize {
        return Packet{}, fmt.Errorf("invalid packet length: %d", length)
    }
    if length > MaxPacketSize {
        return Packet{}, fmt.Errorf("packet too large: %d > %d", length, MaxPacketSize)
    }
    if int(length) != len(data) {
        return Packet{}, fmt.Errorf("length mismatch: header=%d actual=%d", length, len(data))
    }
    return Packet{
        Length:  length,
        Version: data[4],
        CmdID:   binary.BigEndian.Uint32(data[5:9]),
        UserID:  binary.BigEndian.Uint32(data[9:13]),
        SN:      binary.BigEndian.Uint32(data[13:17]),
        Body:    data[HeaderSize:],
    }, nil
}

func BuildPacket(version byte, cmdID uint32, userID uint32, sn uint32, body []byte) []byte {
    length := HeaderSize + len(body)
    data := make([]byte, length)
    binary.BigEndian.PutUint32(data[0:4], uint32(length))
    data[4] = version
    binary.BigEndian.PutUint32(data[5:9], cmdID)
    binary.BigEndian.PutUint32(data[9:13], userID)
    binary.BigEndian.PutUint32(data[13:17], sn)
    copy(data[HeaderSize:], body)
    return data
}

func (c *Client) ReadPacket() ([]byte, error) {
    conn := c.conn()
    if conn == nil {
        return nil, fmt.Errorf("not connected")
    }

    c.readMu.Lock()
    defer c.readMu.Unlock()

    header, err := c.readExactLocked(conn, protocol.HeaderSize)
    if err != nil {
        c.prependReadBufferLocked(header)
        return nil, fmt.Errorf("read header failed: %w", err)
    }
    if err := c.alignPacketHeaderLocked(conn, header); err != nil {
        return nil, err
    }

    length := binary.BigEndian.Uint32(header[:4])
    bodyLength := int(length) - protocol.HeaderSize
    body, err := c.readExactLocked(conn, bodyLength)
    if err != nil {
        partial := make([]byte, 0, len(header)+len(body))
        partial = append(partial, header...)
        partial = append(partial, body...)
        c.prependReadBufferLocked(partial)
        return nil, fmt.Errorf("read body failed: %w", err)
    }

    packet := make([]byte, 0, int(length))
    packet = append(packet, header...)
    packet = append(packet, body...)
    return packet, nil
}

func (c *Client) prependReadBufferLocked(data []byte) {
    if len(data) == 0 {
        return
    }
    restored := make([]byte, 0, len(data)+len(c.readBuffer))
    restored = append(restored, data...)
    restored = append(restored, c.readBuffer...)
    c.readBuffer = restored
}

