MAX_PACKET_LENGTH = 2 * 1024 * 1024

class PacketProcessor:
    def process_recv_packet(self, socket_handle: int, payload: bytes) -> list[PacketData]:
        packets: list[PacketData] = []
        recv_buf = self._recv_bufs.setdefault(socket_handle, bytearray())
        recv_buf.extend(payload)

        while True:
            if len(recv_buf) < 4:
                break
            packet_length = struct.unpack(">I", recv_buf[:4])[0]
            if packet_length < 17 or packet_length > MAX_PACKET_LENGTH:
                self._logger.warning("[recv-drop] socket=%s invalid_length=%s", socket_handle, packet_length)
                recv_buf.clear()
                break
            if len(recv_buf) < packet_length:
                break

            cipher_packet = bytes(recv_buf[:packet_length])
            del recv_buf[:packet_length]
            raw_packet = self.decrypt_packet(cipher_packet) if should_decrypt(cipher_packet, self._client_type) else cipher_packet
            packet = self.parse_packet(raw_packet)

            if packet.cmd_id == 1001:
                self._on_login(packet, socket_handle)
            elif not self._observe_socket(socket_handle, packet, is_send=False):
                continue

            packets.append(packet)
            self._dispatcher.dispatch(packet)
            self._notify_packet_observers("recv", packet)
        return packets

    def parse_packet(self, packet: bytes) -> PacketData:
        length, version, cmd_id, user_id, sn = struct.unpack(">IBIII", packet[:17])
        if length != len(packet):
            raise ValueError(f"packet length mismatch: header={length} actual={len(packet)}")
        return PacketData(length=length, version=version, cmd_id=cmd_id, user_id=user_id, sn=sn, body=packet[17:length])

