class ResourceStore:
    def _row_by_id(self, item_id: int, *, cache_key: str, bundle_name: str, data_key: str, id_key: str, remote_kind: str, normalizer: callable) -> dict[str, Any] | None:
        if item_id <= 0:
            return None
        rows = self._cached_parsed(cache_key, lambda: _load_row_map(self.bundle(bundle_name).get(data_key), id_key))
        cached = rows.get(item_id)
        refresh_cached = remote_kind == "skill" and isinstance(cached, dict) and _remote_skill_row_needs_refresh(cached)
        if isinstance(cached, dict) and not refresh_cached:
            return cached

        payload = self._fetch_remote_row(remote_kind, item_id)
        if not isinstance(payload, dict):
            return cached if isinstance(cached, dict) else None
        row = normalizer(payload, item_id)
        if not isinstance(row, dict):
            return cached if isinstance(cached, dict) else None

        rows[item_id] = row
        self._merge_bundle_row(bundle_name, data_key, item_id, row)
        return row

def _write_bundle_file(self, bundle_name: str, payload: dict[str, Any]) -> None:
    path = self.bundle_path(bundle_name)
    temp_name: str | None = None
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False, dir=str(path.parent), prefix=f"{path.name}.", suffix=".tmp") as handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2)
            handle.write("\n")
            temp_name = handle.name
        Path(temp_name).replace(path)
    except Exception:
        if temp_name is not None:
            Path(temp_name).unlink(missing_ok=True)

