def check_login_title() -> str:
    try:
        response = requests.get(SCHOOL_WEB_URL, timeout=REQUEST_TIMEOUT)
        match = re.search(r"<title>(.*?)</title>", response.text, flags=re.S | re.I)
        if not match:
            return ""
        return match.group(1).strip()
    except requests.RequestException:
        return ""


def is_logged_in(title: str) -> bool:
    if not title:
        return False
    title_l = title.lower()
    return any(marker.lower() in title_l for marker in LOGIN_SUCCESS_MARKERS)

def get_local_ip() -> str:
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.connect(("8.8.8.8", 80))
        ip = sock.getsockname()[0]
        sock.close()
        return ip
    except OSError:
        return ""

def parse_jsonp_payload(text: str) -> dict:
    match = re.match(r"^\s*[A-Za-z0-9_]+\((.*)\)\s*$", text, flags=re.S)
    if not match:
        raise ValueError(f"unexpected response format: {text[:120]}")
    payload = match.group(1)
    return json.loads(payload)

def run_once() -> Literal["already", "recovered", "failed"]:
    title = check_login_title()
    if is_logged_in(title):
        log(f"already online (title: {title})")
        return "already"

    log("not online, trying login")
    if login():
        return "recovered"
    return "failed"


def run_daemon(success_interval: int, failure_interval: int) -> int:
    while True:
        state = run_once()
        sleep_seconds = success_interval if state != "failed" else failure_interval
        log(f"sleep {sleep_seconds}s before next check")
        time.sleep(sleep_seconds)

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Campus network auto-login script (single-run or daemon mode)."
    )
    parser.add_argument(
        "--mode",
        choices=["single", "daemon"],
        default="single",
        help="single: run once then exit; daemon: keep loop running",
    )
    parser.add_argument("--success-interval", type=int, default=300)
    parser.add_argument("--failure-interval", type=int, default=30)
    return parser


def main() -> int:
    args = build_parser().parse_args()
    if args.mode == "daemon":
        return run_daemon(args.success_interval, args.failure_interval)

    state = run_once()
    return 0 if state in {"already", "recovered"} else 1

